  if(action.equals("github-create")){String name=args.optString("repoName"),key=config.get("githubToken","");if(!name.matches("[A-Za-z0-9_.-]{1,100}"))throw new Exception("Valid repository name required");if(key.isEmpty())throw new Exception("Set a GitHub token in Server settings");JSONObject r=remote("https://api.github.com/user/repos",object("name",name,"private",true,"auto_init",true),key);return result("Created private repository "+r.getString("full_name")+"\n"+r.getString("html_url"));}
