  if(action.equals("rewrite"))instruction+=" Return only revised text, preserving the facts and intended meaning.";
  String key=config.get("apiKey","");if(key.isEmpty()&&!config.get("apiBase","").startsWith("http://127.0.0.1")&&!config.get("apiBase","").startsWith("http://localhost"))throw new Exception("AI is not configured. Add a model connection in the app's Server settings. Context, workspace MCP and the Android shell work without a model.");
  JSONArray messages=new JSONArray().put(object("role","system","content",instruction)).put(object("role","user","content",object("request",text,"tone",args.optString("tone","clear"),"language",args.optString("contextLanguage","auto"),"saved_context",retrieved,"conversation",args.optJSONArray("history")==null?new JSONArray():args.getJSONArray("history"),"meaningContext",args.optJSONObject("meaningContext")==null?new JSONObject():args.getJSONObject("meaningContext"),"retrieved_sources",receipts).toString()));
